with raw_data_${grass_region_without_quote} as (
    select
        optimized_json_tuple (
            rcmd_request
            ,'$.requestid_v2.TraceID'
            ,'$.userid'
        ) as (
            request_id
            ,user_id
        )
        ,abtest_group_ids
        ,from_json(
            get_json_object(res_item, '$.sections[0].data')
            ,'ARRAY<string>'
        ) as items
        ,bundle
    from srdi_rt.ods_dispatch_log_for_item_expansion t
    where
        t.regional_date = ${regional_date}
        and t.regional_hour = ${regional_hour}
        and t.grass_region in (${grass_region})
)
,processed_data_${grass_region_without_quote} as (
    select
        request_id
        ,user_id
        ,abtest_group_ids
        ,optimized_json_tuple (
            item
            ,'$.itemid'
            ,'$.expansion_type'
            ,'$.expansion_info.original_item.itemid'
            ,'$.expansion_info.original_item.roi_item_type'
            ,'$.expansion_info.cspu_list'
            ,'$.expansion_info.strategies'
            ,'$.expansion_info.final_itemid'
        ) as (
            runit_item_id
            ,expansion_type
            ,original_item_id
            ,roi_item_type
            ,cspu_list
            ,strategies
            ,final_itemid
        )
        ,bundle
    from raw_data_${grass_region_without_quote}
lateral view explode (items) as item
)
,explode_data_${grass_region_without_quote} as (
    select
        request_id
        ,user_id
        ,abtest_group_ids
        ,runit_item_id
        ,expansion_type
        ,original_item_id
        ,roi_item_type
        ,transform (
            from_json(cspu_list, 'ARRAY<string>')
            ,x -> cast(get_json_object(x, '$.cspu_id') as bigint)
        ) as original_cspu_id
        ,strategy.key as expansion_strategy
        ,final_itemid
        ,optimized_json_tuple (
            strategy.value
            ,'$.has_admittance'
            ,'$.has_candidate'
            ,'$.has_expansion'
            ,'$.admittance_status'
            ,'$.candidate_status'
            ,'$.expansion_status'
            ,'$.before_swap_pos'
            ,'$.after_swap_pos'
            ,'$.ctx_item_type'
            ,'$.winner_ritem_id'
            ,'$.exploration_mode'
        ) as (
            has_admittance
            ,has_candidate
            ,has_expansion
            ,admittance_status
            ,candidate_status
            ,expansion_status
            ,before_swap_pos
            ,after_swap_pos
            ,ctx_item_type
            ,winner_ritem_id
            ,exploration_mode
        )
        ,get_json_object(candidate, '$.item_id') as candidate_item_id
        ,get_json_object(candidate, '$.cspu_id') as candidate_cspu_id
        ,get_json_object(candidate, '$.has_prune') as has_prune
        ,get_json_object(candidate, '$.prune_reason') as prune_reason
        ,get_json_object(candidate, '$.expansion_status') as candidate_expansion_status
        ,get_json_object(candidate, '$.hashtag') as hashtag
        ,get_json_object(candidate, '$.hashtag_statistic') as hashtag_statistic
        ,candidate
        ,bundle
    from processed_data_${grass_region_without_quote}
lateral view explode (map_entries(from_json(strategies, 'MAP<STRING, STRING>'))) s as strategy lateral view outer explode (
        from_json(
            get_json_object(strategy.value, '$.candidates')
            ,'ARRAY<STRING>'
        )
    ) c as candidate
)
insert overwrite
    srdi_mart.dwd_dispatch_log_for_item_expansion partition (
        regional_date = ${regional_date}
        ,regional_hour = ${regional_hour}
        ,grass_region = ${grass_region}
    )
select
    request_id
    ,abtest_group_ids
    ,cast(
        if (
            expansion_type = 'ITEM_EXPANSION_TYPE_NONE'
            ,runit_item_id
            ,original_item_id
        ) as bigint
    ) as original_item_id
    ,original_cspu_id
    ,cast(candidate_item_id as bigint) as candidate_item_id
    ,cast(candidate_cspu_id as bigint) as candidate_cspu_id
    ,expansion_strategy
    ,cast(has_admittance as boolean) as has_admittance
    ,cast(has_candidate as boolean) as has_candidate
    ,cast(has_expansion as boolean) as has_expansion
    ,admittance_status
    ,candidate_status
    ,cast(has_prune as boolean) as has_prune
    ,prune_reason
    ,expansion_status as expansion_status
    ,bundle
    ,candidate_expansion_status as candidate_expansion_status
    ,roi_item_type as roi_item_type
    ,cast(user_id as bigint) as user_id
    ,cast(before_swap_pos as int) as before_swap_pos
    ,cast(after_swap_pos as int) as after_swap_pos
    ,cast(final_itemid as bigint) as final_itemid
    ,cast(ctx_item_type as int) as ctx_item_type
    ,cast(winner_ritem_id as bigint) as winner_ritem_id
    ,hashtag as hashtag
    ,hashtag_statistic as hashtag_statistic
    ,exploration_mode as exploration_mode
from explode_data_${grass_region_without_quote}
;
